import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"探测、诊断与故障判定","description":"","frontmatter":{"title":"探测、诊断与故障判定"},"headers":[],"relativePath":"zh/guide/probe-diagnosis.md","filePath":"zh/guide/probe-diagnosis.md","lastUpdated":0}`),a={name:`zh/guide/probe-diagnosis.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_5-探测、诊断与故障判定" tabindex="-1">5. 探测、诊断与故障判定 <a class="header-anchor" href="#_5-探测、诊断与故障判定" aria-label="Permalink to “5. 探测、诊断与故障判定”">​</a></h1><h2 id="_5-1-probe-与-diagnosis-分离" tabindex="-1">5.1 Probe 与 Diagnosis 分离 <a class="header-anchor" href="#_5-1-probe-与-diagnosis-分离" aria-label="Permalink to “5.1 Probe 与 Diagnosis 分离”">​</a></h2><p>Probe 负责收集事实。</p><p>Diagnosis 根据多个事实判断故障原因。</p><p>例如：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Probe A: Wi-Fi 已连接</span></span>
<span class="line"><span>Probe B: 已取得 IP 地址</span></span>
<span class="line"><span>Probe C: 默认网关可达</span></span>
<span class="line"><span>Probe D: 公网 IP 不可达</span></span>
<span class="line"><span>Probe E: 代理本地端口可连接</span></span>
<span class="line"><span>Probe F: 代理认证失败</span></span></code></pre></div><p>这些证据不能简单合并成“网络故障”。</p><p>诊断结果应包括：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Diagnosis</span></span>
<span class="line"><span>├── fault_code</span></span>
<span class="line"><span>├── summary</span></span>
<span class="line"><span>├── confidence (optional)</span></span>
<span class="line"><span>├── evidence_refs[]</span></span>
<span class="line"><span>├── affected_resources[]</span></span>
<span class="line"><span>├── recommended_actions[]</span></span>
<span class="line"><span>└── limitations[]</span></span></code></pre></div><p><code>confidence</code> 是可选的规则置信度，不应伪装成统计学概率。</p><h2 id="_5-2-故障类型" tabindex="-1">5.2 故障类型 <a class="header-anchor" href="#_5-2-故障类型" aria-label="Permalink to “5.2 故障类型”">​</a></h2><p>第一版至少区分：</p><ul><li><code>process_exited</code></li><li><code>service_stopped</code></li><li><code>probe_timeout</code></li><li><code>network_disconnected</code></li><li><code>gateway_unreachable</code></li><li><code>dns_failure</code></li><li><code>proxy_connection_failed</code></li><li><code>proxy_authentication_failed</code></li><li><code>remote_endpoint_unreachable</code></li><li><code>plugin_unavailable</code></li><li><code>dependency_unsatisfied</code></li><li><code>recovery_action_failed</code></li><li><code>verification_failed</code></li><li><code>unknown_failure</code></li></ul><p>未知故障不得直接触发所有可能的恢复动作。</p><h2 id="_5-3-连续失败与抖动抑制" tabindex="-1">5.3 连续失败与抖动抑制 <a class="header-anchor" href="#_5-3-连续失败与抖动抑制" aria-label="Permalink to “5.3 连续失败与抖动抑制”">​</a></h2><p>不能因为一次超时就立即重启服务。</p><p>健康策略需要支持：</p><ul><li>连续失败阈值。</li><li>连续成功阈值。</li><li>探测超时。</li><li>失败窗口。</li><li>恢复确认窗口。</li><li>故障冷却时间。</li></ul><p>例如：</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">health_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10s</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3s</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  failure_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  success_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span></code></pre></div><p>此处为示例值，实际值应按资源类型设置。</p><p>阈值只负责决定是否进入故障状态，不应被用来掩盖持续异常。</p><h2 id="_5-4-p0-的探测范围" tabindex="-1">5.4 P0 的探测范围 <a class="header-anchor" href="#_5-4-p0-的探测范围" aria-label="Permalink to “5.4 P0 的探测范围”">​</a></h2><p>P0 只实现：</p><ul><li>Process Probe。</li><li>Exec Probe。</li></ul><p>P0 暂不实现 HTTP Probe。</p><p>Process Probe 用于检查进程是否存在以及必要的进程属性。</p><p>Exec Probe 用于执行受控的检查命令，并解析：</p><ul><li>退出码。</li><li>标准输出。</li><li>标准错误。</li><li>超时。</li><li>启动失败。</li><li>输出是否被截断。</li></ul><p>Exec Probe 必须限制运行时间和输出大小，并在超时时清理进程树。Windows 上不能只终止父进程而留下孤儿子进程。</p><p>后续版本再加入网络、HTTP、服务管理和代理专用探测器。</p><hr>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};